// A seed's hosted demo at demo.<domain>, generated by `rer deploy --demo`.
// GET / shows the start page (a Turnstile managed widget that starts the demo by itself).
// POST /__demo/start checks the visitor's IP rate limit, Turnstile and capacity,
// then starts a native isolate of their own, signs its owner in and sets the
// rer_demo cookie. The page's script asks for JSON (Accept: application/json) to
// show its progress and failures; a plain form post gets the 303 or the page. Every request with that cookie goes to the visitor's
// isolate; nothing else on this host is reachable.
import { operatorPage } from './operator.mjs';
import { measured, testHost } from './measurement.mjs';
import { bounded, category, report } from './diagnostics.mjs';
import { startPage, demoCookie, clearCookie } from './pages.mjs';

export { DemoCapacity } from './capacity.mjs';

const HOUR = 60 * 60_000;
const home = () => new Response(null, { status: 303, headers: { location: '/' } });

/** The visitor's demo from its cookie; ids are checked by idFromString, so a forged one is no demo. */
function demoId(request, env) {
  const value = (request.headers.get('cookie') ?? '').split(';').map(part => part.trim()).find(part => part.startsWith('rer_demo='))?.slice(9);
  if (!value) return null;
  try { return env.DEMO.idFromString(value); } catch { return null; }
}

// The demo's end in the visitor's time zone, retained in runtime settings.
function localTime(time, timeZone = 'UTC') {
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit', timeZoneName: 'longOffset' }).formatToParts(time).map(part => [part.type, part.value]));
  return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}:${parts.second}${parts.timeZoneName === 'GMT' ? '+00:00' : parts.timeZoneName.slice(3)}`;
}

async function human(env, token, ip) {
  if (typeof token !== 'string' || !token || token.length > 2048) return false;
  const body = new URLSearchParams({ secret: env.TURNSTILE_SECRET_KEY, response: token });
  if (ip) body.set('remoteip', ip);
  const response = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', { method: 'POST', body, signal: AbortSignal.timeout(5000) });
  const result = response.ok ? await response.json() : {};
  if (result.success !== true) console.error('Turnstile refused a start:', response.status, JSON.stringify(result['error-codes'] ?? []));
  return result.success === true;
}

const wantsJSON = request => request.headers.get('accept') === 'application/json';
function refusal(request, env, status, notice, headers = {}) {
  const correlation = headers['x-rer-demo-correlation'] ?? crypto.randomUUID();
  headers = { 'cache-control': 'no-store', ...headers, 'x-rer-demo-correlation': correlation };
  report(correlation, Date.now(), 'refused', { status });
  return wantsJSON(request) ? Response.json({ notice }, { status, headers }) : startPage(env, { status, notice, headers });
}

function progress(request, env, id, state) {
  const headers = new Headers({ 'cache-control': 'no-store' });
  if (state.correlation) headers.set('x-rer-demo-correlation', state.correlation);
  if (state.phase === 'failed') return refusal(request, env, 502, 'The demo did not start. Try again.', { ...Object.fromEntries(headers), 'set-cookie': clearCookie(env) });
  headers.append('set-cookie', demoCookie(env, id.toString()));
  if (state.phase === 'starting') {
    headers.set('retry-after', '1');
    if (wantsJSON(request)) return Response.json({ pending: true }, { status: 202, headers });
    // A plain form keeps the same visitor reservation while the copy starts.
    return startPage(env, { status: 202, pending: true, headers: Object.fromEntries(headers) });
  }
  for (const cookie of state.cookies) headers.append('set-cookie', cookie);
  if (wantsJSON(request)) return Response.json({ location: state.location }, { headers });
  headers.set('location', state.location);
  return new Response(null, { status: 303, headers });
}

// The page asks again as soon as this answers: the object holds a pending
// answer until the start changes. A slow answer is still pending; the start's
// own budget decides failure.
async function status(request, env) {
  const id = demoId(request, env);
  if (!id) return refusal(request, env, 410, 'This demo has ended. Start a new demo.');
  let state;
  try { state = await bounded(env.DEMO.get(id).status(1500), 3500); }
  catch { state = { phase: 'starting' }; }
  return progress(request, env, id, state);
}

async function start(request, env, ctx) {
  const correlation = crypto.randomUUID();
  const refuse = (status, notice, headers = {}) => refusal(request, env, status, notice, { 'x-rer-demo-correlation': correlation, ...headers });
  if (request.headers.get('origin') !== env.DEMO_ORIGIN) return refuse(403, 'Start the demo from this page.');
  if (testHost(env) && !await measured(request, env)) return refuse(403, 'This is a test host: it starts demos only for its operator\'s measurement runs.');
  let demo;
  const started = Date.now();
  try {
    const ip = request.headers.get('cf-connecting-ip') ?? '';
    if (!(await bounded(env.STARTS.limit({ key: ip }), 1000)).success) return refuse(429, 'Too many demos started from your network. Try again in a minute.');
    const form = await bounded(request.formData(), 1000);
    if (!await bounded(human(env, form.get('cf-turnstile-response'), ip), 5000)) return refuse(403, 'The check did not pass. Try again.');
    // A retry while the original start is pending resumes that copy, not a
    // second reservation that the visitor can never use.
    const prior = demoId(request, env);
    if (prior) {
      const state = await bounded(env.DEMO.get(prior).status(), 1000);
      if (state.phase === 'starting') return progress(request, env, prior, state);
    }
    const id = env.DEMO.newUniqueId(), ends = Date.now() + HOUR;
    const capacity = env.CAPACITY.get(env.CAPACITY.idFromName('capacity'));
    // A lost handoff occupies a place for at most a minute. The object extends
    // it to the demo's end only after health and owner admission succeed.
    if (!await bounded(capacity.acquire(id.toString(), Date.now() + 60_000, Number(env.DEMO_MAX_INSTANCES), correlation), 2000)) {
      return refuse(503, 'Every demo is in use right now. Try again in a few minutes.');
    }
    // Who holds the place: automated browsers pass Turnstile's testing keys.
    report(correlation, started, 'admitted', { agent: (request.headers.get('user-agent') ?? '').slice(0, 160), network: request.cf?.asOrganization ?? null });
    demo = env.DEMO.get(id);
    const begun = demo.begin({ correlation, clientIp: ip, origin: env.DEMO_ORIGIN, originVar: env.DEMO_ORIGIN_VAR, ends, endsLocal: localTime(ends, request.cf?.timezone), settings: JSON.parse(env.DEMO_SETTINGS) });
    // A new object can take seconds to answer. That is a slow start, not a
    // failed one: the page polls this copy, and a begin that later fails ends
    // it and releases its place.
    let slow;
    const state = await Promise.race([begun, new Promise(resolve => { slow = setTimeout(resolve, 2000, null); })]).finally(() => clearTimeout(slow));
    if (!state) {
      report(correlation, started, 'begin-pending');
      ctx.waitUntil(begun.catch(error => {
        report(correlation, started, 'failed', { error: category(error) });
        return bounded(demo.end(), 6000);
      }).catch(cleanup => report(correlation, started, 'cleanup', { error: category(cleanup) })));
    }
    return progress(request, env, id, { ...(state ?? { phase: 'starting' }), correlation });
  } catch (error) {
    report(correlation, started, 'failed', { error: category(error) });
    // Cleanup runs independently of the response: retries never wait on it.
    if (demo) ctx.waitUntil(bounded(demo.end(), 6000).catch(cleanup => report(correlation, started, 'cleanup', { error: category(cleanup) })));
    return refuse(502, 'The demo did not start. Try again.', correlation ? { 'x-rer-demo-correlation': correlation } : {});
  }
}

// The visitor explicitly abandons this copy before running a fresh human check.
// Wait for destruction and place release; a failed cleanup must retain the cookie
// so another click can finish it instead of silently leaking a reservation.
async function cancel(request, env) {
  if (request.headers.get('origin') !== env.DEMO_ORIGIN) return refusal(request, env, 403, 'Start the demo from this page.');
  const id = demoId(request, env);
  try { if (id) await bounded(env.DEMO.get(id).end(), 6000); }
  catch { return refusal(request, env, 503, 'The previous demo could not be ended. Try again.'); }
  return new Response(null, { status: 204, headers: { 'cache-control': 'no-store', 'set-cookie': clearCookie(env) } });
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const primary = url.origin === env.DEMO_ORIGIN;
    const secondary = JSON.parse(env.DEMO_SECONDARY_ORIGINS ?? '[]').includes(url.origin);
    if (!primary && !secondary) return new Response('Not found.', { status: 404 });
    if (!primary && url.pathname.startsWith('/__demo/')) return new Response('Start the demo on its primary host.', { status: 403 });
    if (url.pathname.startsWith('/__demo/operator/')) return operatorPage(request, env, url.pathname.slice('/__demo/operator/'.length));
    if (url.pathname === '/__demo/start') return request.method === 'POST' ? start(request, env, ctx) : home();
    if (url.pathname === '/__demo/status') return request.method === 'GET' ? status(request, env) : home();
    if (url.pathname === '/__demo/cancel') return request.method === 'POST' ? cancel(request, env) : home();
    const id = demoId(request, env);
    if (id) {
      // The JSON start leaves the browser on /. Reloading it must keep the
      // pending copy on the progress page until health and owner claim finish.
      if (primary && url.pathname === '/' && ['GET', 'HEAD'].includes(request.method)) {
        // A recovering object may answer slowly; its own fetch below still
        // serves the demo or its ended page.
        const state = await bounded(env.DEMO.get(id).status(), 2000).catch(() => null);
        if (state?.phase === 'starting') return progress(request, env, id, state);
      }
      return env.DEMO.get(id).fetch(request);
    }
    if (!['GET', 'HEAD'].includes(request.method)) return new Response('Start a demo first.', { status: 403 });
    if (!primary) return new Response(null, { status: 303, headers: { location: env.DEMO_ORIGIN + '/' } });
    if (url.pathname !== '/') return home();
    return startPage(env);
  },
};
